 const auto prior=decodeSave(*c.legacySource,source);auto migrated=saved.session;for(int f:{444,445}){need(!migrated.worldFlags.at(c.facts.switches.at(f)),"Migration fabricated power");migrated.worldFlags.erase(c.facts.switches.at(f));auto invalid=saved;invalid.session.worldFlags.erase(c.facts.switches.at(f));rejects([&]{validateSave(c,invalid);});}need(migrated==prior.session&&saved.scene==prior.scene,"Migration changed existing progress");auto invalid=saved;invalid.session.worldFlags[c.facts.switches.at(445)]=true;rejects([&]{validateSave(c,invalid);});auto unknown=Json::parse(source);unknown["content"]="post-f5-g2-normal-unknown";rejects([&]{decodeSave(c,unknown.dump());});
 auto e=fixture(c,saved);GameSession state(c.items,e.session,c.facts);CombatScene scene(c,state,e,safe);open(scene);auto p=pics(c,scene);for(int i=1;i<=9;++i){need(p.at(15+i).transparency==((i==2||i==3||i==8)?0:100),"Wrong original initial cell");}need(at(p.at(25).position,115,84),"Opening confirm penetrated panel");
 scene.update(both(InputAction::Down,InputAction::Right));p=pics(c,scene);need(p.size()==1&&at(p.at(25).position,159,84)&&p.at(25).durationTenths==0,"Direction priority/glyph animation wrong");scene.update(both(InputAction::Left,InputAction::Right));p=pics(c,scene);need(at(p.at(25).position,203,84),"Right must precede Left");button(scene,InputAction::Right);button(scene,InputAction::Up);p=pics(c,scene);need(at(p.at(25).position,115,156),"Row/column wrap wrong");button(scene,InputAction::Down);pics(c,scene);
 const auto& profile=c.catalog.at("nine_cell_panels").at("power");int cursor=1;
